//! One test per file in engine/conformance/vectors (generated by build.rs).

include!(concat!(env!("OUT_DIR"), "/vectors_generated.rs"));

const _: () = assert!(VECTOR_COUNT > 0, "no conformance vectors found");

#[test]
fn runner_rejects_a_wrong_expectation() {
    // Guards against a runner that silently passes everything.
    let v = r#"{"format":1,"name":"neg","steps":[
        {"op":"init"},
        {"op":"expect_state","state":{"sim_speed":2}}
    ]}"#;
    assert!(fc4_conformance::run_vector_text(v).is_err());
    let v = r#"{"format":1,"name":"neg","steps":[
        {"op":"pause"},
        {"op":"expect_events","events":[]}
    ]}"#;
    assert!(fc4_conformance::run_vector_text(v).is_err());
    let v = r#"{"format":1,"name":"neg","steps":[{"op":"no_such_op"}]}"#;
    assert!(fc4_conformance::run_vector_text(v).is_err());
}
